QUnit.module("highlightedHours",function(e){e.beforeEach(function(){$("#qunit-fixture").html('<div id="cal"></div>')}),e.afterEach(function(){try{$("#cal").bsCalendar("destroy")}catch(e){}}),QUnit.test("renders a single highlightedHours object",function(e){const t=e.async(1);$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-15",hourSlots:{start:8,end:12},highlightedHours:{daysOfWeek:[1],startTime:"09:00",endTime:"11:00",color:"rgba(10, 20, 30, 0.25)"}}),setTimeout(function(){const a=$("#cal").find('[data-day-hour="9"]').css("background-color"),r=$("#cal").find('[data-day-hour="8"]').css("background-color");e.strictEqual(a,"rgba(10, 20, 30, 0.25)","matching hour row receives the configured color"),e.notStrictEqual(r,"rgba(10, 20, 30, 0.25)","non-matching hour row is not highlighted"),t()},0)}),QUnit.test("renders highlightedHours arrays with separate colors",function(e){const t=e.async(1);$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-20",hourSlots:{start:9,end:15},highlightedHours:[{daysOfWeek:[1,2,3,4,5],startTime:"09:00",endTime:"17:00",mode:"exclusive",color:"rgba(10, 20, 30, 0.25)"},{daysOfWeek:[6],startTime:"10:00",endTime:"14:00",mode:"preferred",color:"rgba(40, 120, 60, 0.3)"}]}),setTimeout(function(){const a=$("#cal").find('[data-day-hour="10"]').css("background-color"),r=$("#cal").find('[data-day-hour="14"]').css("background-color");e.strictEqual(a,"rgba(40, 120, 60, 0.3)","matching array item controls the row color"),e.notStrictEqual(r,"rgba(40, 120, 60, 0.3)","range end is exclusive for row highlighting"),t()},0)}),QUnit.test("sets inHighlightedHours when appointment is contained in any range",function(e){const t=e.async(1);$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-15",highlightedHours:[{daysOfWeek:[1,2,3,4,5],startTime:"09:00",endTime:"17:00",mode:"exclusive",color:"primary"},{daysOfWeek:[6],startTime:"10:00",endTime:"14:00",mode:"preferred",color:"success"}]}),$("#cal").one("added.bs.calendar",function(a,r,i){e.strictEqual(i.inHighlightedHours,!0,"appointment is inside the weekday range"),e.strictEqual(i.highlightedHours.canWork,!0,"exclusive range allows work inside the configured slot"),e.strictEqual(i.highlightedHours.mode,"exclusive"),t()}),$("#cal").bsCalendar("addAppointment",{title:"Inside highlighted hours",start:"2026-06-15 10:00:00",end:"2026-06-15 11:00:00"})}),QUnit.test("exclusive mode blocks appointments outside the exclusive range",function(e){const t=e.async(1);$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-15",highlightedHours:[{daysOfWeek:[1],startTime:"09:00",endTime:"17:00",mode:"exclusive",color:"success"}]}),$("#cal").one("added.bs.calendar",function(a,r,i){e.strictEqual(i.inHighlightedHours,!1,"appointment is outside the exclusive range"),e.strictEqual(i.highlightedHours.canWork,!1,"outside exclusive range is not workable"),e.strictEqual(i.highlightedHours.reason,"outsideExclusive"),t()}),$("#cal").bsCalendar("addAppointment",{title:"Outside exclusive hours",start:"2026-06-15 18:00:00",end:"2026-06-15 19:00:00"})}),QUnit.test("blocked mode blocks overlapping appointments",function(e){const t=e.async(1);$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-21",highlightedHours:[{daysOfWeek:[0],startTime:"00:00",endTime:"23:59",mode:"blocked",color:"danger"}]}),$("#cal").one("added.bs.calendar",function(a,r,i){e.strictEqual(i.highlightedHours.canWork,!1,"blocked range is not workable"),e.strictEqual(i.highlightedHours.isBlocked,!0),e.strictEqual(i.highlightedHours.mode,"blocked"),t()}),$("#cal").bsCalendar("addAppointment",{title:"Blocked Sunday work",start:"2026-06-21 10:00:00",end:"2026-06-21 11:00:00"})}),QUnit.test("preferred mode keeps appointments workable and marks them preferred",function(e){const t=e.async(1);$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-20",highlightedHours:[{daysOfWeek:[6],startTime:"10:00",endTime:"14:00",mode:"preferred",color:"grey"}]}),$("#cal").one("added.bs.calendar",function(a,r,i){e.strictEqual(i.highlightedHours.canWork,!0,"preferred range is workable"),e.strictEqual(i.highlightedHours.isPreferred,!0),e.strictEqual(i.highlightedHours.mode,"preferred"),t()}),$("#cal").bsCalendar("addAppointment",{title:"Preferred Saturday work",start:"2026-06-20 11:00:00",end:"2026-06-20 12:00:00"})}),QUnit.test("setHighlightedHours accepts arrays at runtime",function(e){$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-15"}),$("#cal").bsCalendar("setHighlightedHours",[{daysOfWeek:[1],startTime:"08:00",endTime:"12:00",color:"rgba(10, 20, 30, 0.25)"}]);const t=$("#cal").data("bsCalendar").settings;e.ok(Array.isArray(t.highlightedHours),"runtime value remains an array"),e.strictEqual(t.highlightedHours[0].startTime,"08:00")})});